// Server attribute "active" -> chip Online (xanh) / Offline (đỏ)
var chip = 'display:inline-flex;align-items:center;gap:6px;padding:3px 12px;border-radius:12px;font-weight:600;font-size:12.5px;';
var dot = 'width:8px;height:8px;border-radius:50%;display:inline-block;';
if (value === undefined || value === null || value === '') {
    return '<span style="' + chip + 'background:#f1f5f9;color:#64748b"><span style="' + dot + 'background:#94a3b8"></span>Chưa kết nối</span>';
}
var on = value === true || String(value).toLowerCase() === 'true';
return on
    ? '<span style="' + chip + 'background:#dcfce7;color:#15803d"><span style="' + dot + 'background:#16a34a"></span>Online</span>'
    : '<span style="' + chip + 'background:#fee2e2;color:#b91c1c"><span style="' + dot + 'background:#dc2626"></span>Offline</span>';

// Hiển thị thời điểm (ms) dạng HH:mm:ss dd/MM/yyyy
if (value === undefined || value === null || value === '' || Number(value) <= 0) {
    return '<span style="color:#94a3b8">--</span>';
}
var d = new Date(Number(value));
function p(n) { return (n < 10 ? '0' : '') + n; }
return p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds()) + ' ' +
    p(d.getDate()) + '/' + p(d.getMonth() + 1) + '/' + d.getFullYear();

